module TopModule (
    input  logic [254:0] in,
    output logic [7:0]   out
);

    always_comb begin
        logic [7:0] count;
        count = 8'd0;
        for (int i = 0; i < 255; i++) begin
            if (in[i]) begin
                count = count + 1'b1;
            end
        end
        out = count;
    end

endmodule
